<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/customer-auth.php';require_once dirname(__DIR__).'/crm/core.php';require_once dirname(__DIR__).'/notifications/max.php';
function ma_installed():bool{return crm_query("SELECT state FROM nd_schema_migrations WHERE version='024_max_identity'")->fetchColumn()==='applied';}
function ma_gate():void{ca_gate();if(!ma_installed()||(config()['max_miniapp_enabled']??false)!==true)ca_fail(503,'max_not_configured','Привязка MAX закрыта до проверки политики и настройки мини-приложения владельцем.');}
function ma_token():string{$s=max_read();$token=$s['token']??'';if(!is_string($token)||!preg_match('/^[A-Za-z0-9._:-]{20,512}$/D',$token))ca_fail(503,'max_not_configured','Токен существующего бота не настроен.');return $token;}
/** https://dev.max.ru/docs/webapps/validation — reject duplicates before decoding/canonical sorting. */
function ma_validate(string $raw,string $token,?int $now=null):array{
 $now??=time();if($raw===''||strlen($raw)>16384||preg_match('/%(?![0-9a-fA-F]{2})/',$raw))ca_fail(401,'invalid_max_identity','Некорректные стартовые данные MAX.');$data=[];
 foreach(explode('&',$raw) as $pair){$parts=explode('=',$pair,2);if(count($parts)!==2)ca_fail(401,'invalid_max_identity','Некорректные стартовые данные MAX.');$key=rawurldecode($parts[0]);$value=rawurldecode($parts[1]);if(!preg_match('/^[A-Za-z0-9_]+$/D',$key)||array_key_exists($key,$data)||!mb_check_encoding($value,'UTF-8')||count($data)>=24)ca_fail(401,'invalid_max_identity','Повторяющиеся или некорректные параметры MAX.');$data[$key]=$value;}
 $hash=$data['hash']??'';unset($data['hash']);if(!preg_match('/^[a-f0-9]{64}$/D',$hash)||!isset($data['auth_date'],$data['user'])||!preg_match('/^[0-9]{10}$/D',$data['auth_date']))ca_fail(401,'invalid_max_identity','Не хватает проверяемых данных MAX.');$at=(int)$data['auth_date'];if($at>$now+30||$at<$now-300)ca_fail(401,'max_identity_expired','Откройте мини-приложение MAX заново: стартовые данные истекли.');ksort($data,SORT_STRING);$lines=[];foreach($data as $k=>$v)$lines[]=$k.'='.$v;$secret=hash_hmac('sha256',$token,'WebAppData',true);$expected=hash_hmac('sha256',implode("\n",$lines),$secret);if(!hash_equals($expected,$hash))ca_fail(401,'invalid_max_identity','Подпись MAX не подтверждена.');
 try{$user=json_decode($data['user'],true,32,JSON_THROW_ON_ERROR|JSON_BIGINT_AS_STRING);}catch(Throwable $e){ca_fail(401,'invalid_max_identity','Профиль MAX не подтверждён.');}$id=is_array($user)?($user['id']??null):null;if(!(is_int($id)||is_string($id))||!preg_match('/^[1-9][0-9]{0,18}$/D',(string)$id)||strlen((string)$id)===19&&strcmp((string)$id,'9223372036854775807')>0)ca_fail(401,'invalid_max_identity','Идентификатор MAX некорректен.');return ['user_id'=>(string)$id,'proof_hash'=>hash('sha256',$expected.':'.$id.':'.$at),'expires_at'=>$at+300];
}
function ma_claim(array $d):array{$raw=$d['init_data']??'';if(!is_string($raw))ca_fail(401,'invalid_max_identity','Проверьте запуск в MAX.');return ma_validate($raw,ma_token());}
function ma_bootstrap(array $d):array{$claim=ma_claim($d);$nonce=bin2hex(random_bytes(32));crm_atomic(function()use($claim,$nonce){crm_query('DELETE FROM nd_max_launches WHERE expires_at<?',[time()]);if(crm_query('SELECT proof_hash FROM nd_max_launches WHERE proof_hash=? FOR UPDATE',[$claim['proof_hash']])->fetchColumn())ca_fail(409,'max_launch_reused','Этот запуск уже обработан. Откройте мини-приложение заново.');crm_query('INSERT INTO nd_max_launches(proof_hash,nonce_hash,expires_at) VALUES (?,?,?)',[$claim['proof_hash'],hash('sha256',$nonce),$claim['expires_at']]);});$linked=(bool)crm_query('SELECT account_id FROM nd_max_account_links WHERE max_user_id=?',[$claim['user_id']])->fetchColumn();return ['ok'=>true,'nonce'=>$nonce,'linked'=>$linked,'policy'=>ca_privacy_settings()];}
function ma_consume(array $claim,array $d):void{$nonce=$d['nonce']??'';$p=crm_query('SELECT * FROM nd_max_launches WHERE proof_hash=? FOR UPDATE',[$claim['proof_hash']])->fetch();if(!is_string($nonce)||!$p||$p['consumed_at']!==null||(int)$p['expires_at']<=time()||!hash_equals($p['nonce_hash'],hash('sha256',$nonce)))ca_fail(409,'max_launch_reused','Запуск недействителен, истёк или уже использован.');crm_query('UPDATE nd_max_launches SET consumed_at=? WHERE proof_hash=?',[time(),$claim['proof_hash']]);}
function ma_issue(string $max,int $account):array{$new=ca_new_session($account);crm_query('INSERT INTO nd_max_sessions(token_hash,max_user_id,expires_at) VALUES (?,?,?)',[hash('sha256',$new['raw']),$max,$new['expiry']]);crm_query("INSERT INTO nd_max_account_events(max_user_id,account_id,action) VALUES (?,?,'LOGIN')",[$max,$account]);return ['ok'=>true,'session_token'=>$new['raw'],'csrf'=>$new['csrf'],'expires_at'=>$new['expiry']];}
function ma_login(array $d,bool $link):array{
 $claim=ma_claim($d);$a=null;if($link){$email=ca_email($d);ca_rate('max_link_identity',5,$email);$p=$d['password']??'';$q=crm_query('SELECT id FROM nd_customer_accounts WHERE email=?',[$email])->fetchColumn();$a=$q?ca_account((int)$q):false;if(!is_string($p)||strlen($p)>1024||!$a||!ca_account_allowed($a)||!password_verify($p,$a['password_hash']??''))ca_fail(401,'login_failed','Не удалось подтвердить существующий аккаунт.');if(!ca_paid_order((int)$a['customer_id']))ca_fail(409,'payment_required','Привязка возможна только для клиента с подтверждённой оплатой.');if(($d['confirm_link']??false)!==true)ca_fail(422,'link_confirmation_required','Подтвердите добровольную привязку MAX к этому аккаунту.');$policy=ca_privacy_settings();if(($d['consent']??false)!==true||($d['policy_version']??'')!==$policy['version'])ca_fail(422,'consent_required','Отдельно подтвердите действующую политику кабинета.');}
 return crm_atomic(function()use($claim,$d,$link,$a){ma_consume($claim,$d);$existing=crm_query('SELECT * FROM nd_max_account_links WHERE max_user_id=? FOR UPDATE',[$claim['user_id']])->fetch();if($link){$current=ca_account((int)$a['id'],true);if(!ca_account_allowed($current)||!hash_equals($current['password_hash']??'',$a['password_hash']??''))ca_fail(401,'login_failed','Аккаунт изменился.');$other=crm_query('SELECT max_user_id FROM nd_max_account_links WHERE account_id=? FOR UPDATE',[$a['id']])->fetchColumn();if($existing&&(int)$existing['account_id']!==(int)$a['id']||$other&&(string)$other!==$claim['user_id'])ca_fail(409,'max_link_conflict','Аккаунт уже связан. Сначала отзовите прежнюю привязку в своём кабинете.');if(!$existing){crm_query('INSERT INTO nd_max_account_links(max_user_id,account_id) VALUES (?,?)',[$claim['user_id'],$a['id']]);crm_query("INSERT INTO nd_max_account_events(max_user_id,account_id,action) VALUES (?,?,'LINKED')",[$claim['user_id'],$a['id']]);}ca_record_consent((int)$a['id'],ca_privacy_settings(),'reconsent');$account=(int)$a['id'];}
 else{if(!$existing)ca_fail(403,'max_not_linked','Сначала привяжите подтверждённый оплаченный аккаунт.');$current=ca_account((int)$existing['account_id'],true);if(!ca_account_allowed($current)||!ca_current_consent($current))ca_fail(403,'max_account_unavailable','Проверьте вход и актуальное согласие в клиентском кабинете.');$account=(int)$current['id'];}return ma_issue($claim['user_id'],$account);});
}
function ma_unlink(array $d):array{$s=ca_session(true);$a=ca_account((int)($s['account_id']??0));$password=$d['password']??'';if(!ca_account_allowed($a)||!is_string($password)||!password_verify($password,$a['password_hash']??''))ca_fail(401,'login_failed','Подтвердите пароль действующего аккаунта.');return crm_atomic(function()use($a){$link=crm_query('SELECT * FROM nd_max_account_links WHERE account_id=? FOR UPDATE',[$a['id']])->fetch();if(!$link)return ['ok'=>true];crm_query('DELETE c FROM nd_customer_sessions c JOIN nd_max_sessions m ON m.token_hash=c.token_hash WHERE m.max_user_id=?',[$link['max_user_id']]);crm_query('DELETE FROM nd_max_account_links WHERE max_user_id=?',[$link['max_user_id']]);crm_query("INSERT INTO nd_max_account_events(max_user_id,account_id,action) VALUES (?,?,'UNLINKED')",[$link['max_user_id'],$a['id']]);return ['ok'=>true,'max_sessions_revoked'=>true];});}
